def rotate_90_cw(grid):
    """Rotate 90 degrees clockwise"""
    n = len(grid)
    result = [[grid[n-1-j][i] for j in range(n)] for i in range(n)]
    return result

def rotate_90_ccw(grid):
    """Rotate 90 degrees counter-clockwise (or 270 CW)"""
    n = len(grid)
    result = [[grid[j][n-1-i] for j in range(n)] for i in range(n)]
    return result

def rotate_180(grid):
    """Rotate 180 degrees"""
    n = len(grid)
    result = [[grid[n-1-i][n-1-j] for j in range(n)] for i in range(n)]
    return result

